`timescale 1ns/1ps
// Standalone TX protocol smoke test: DOES NOT instantiate device IP.
module tb_udp_ipv4_frame_tx;
    reg clk=0;
    always #4 clk=~clk;
    reg rst=1;
    reg start=0;
    reg [319:0] payload=320'h4650474101080102000000010001B2070000000100010002000061A8000100020000000354454332;
    wire [7:0] tx_byte;
    wire tx_en,busy,done;
    integer seen=0;
    integer done_seen=0;
    // Independent golden Ethernet frame reference generated by Python crc32.
    // Validates all 94 emitted bytes, including IPv4 checksum and FCS.
    function automatic [7:0] expected_byte(input integer idx);
      begin
        case(idx)
            0: expected_byte=8'h55;
            1: expected_byte=8'h55;
            2: expected_byte=8'h55;
            3: expected_byte=8'h55;
            4: expected_byte=8'h55;
            5: expected_byte=8'h55;
            6: expected_byte=8'h55;
            7: expected_byte=8'hD5;
            8: expected_byte=8'hFF;
            9: expected_byte=8'hFF;
           10: expected_byte=8'hFF;
           11: expected_byte=8'hFF;
           12: expected_byte=8'hFF;
           13: expected_byte=8'hFF;
           14: expected_byte=8'h02;
           15: expected_byte=8'h15;
           16: expected_byte=8'h66;
           17: expected_byte=8'h00;
           18: expected_byte=8'h00;
           19: expected_byte=8'h01;
           20: expected_byte=8'h08;
           21: expected_byte=8'h00;
           22: expected_byte=8'h45;
           23: expected_byte=8'h00;
           24: expected_byte=8'h00;
           25: expected_byte=8'h44;
           26: expected_byte=8'h00;
           27: expected_byte=8'h00;
           28: expected_byte=8'h40;
           29: expected_byte=8'h00;
           30: expected_byte=8'h40;
           31: expected_byte=8'h11;
           32: expected_byte=8'hB6;
           33: expected_byte=8'h4F;
           34: expected_byte=8'hC0;
           35: expected_byte=8'hA8;
           36: expected_byte=8'h01;
           37: expected_byte=8'h0A;
           38: expected_byte=8'hC0;
           39: expected_byte=8'hA8;
           40: expected_byte=8'h01;
           41: expected_byte=8'hFF;
           42: expected_byte=8'h13;
           43: expected_byte=8'h88;
           44: expected_byte=8'h13;
           45: expected_byte=8'h89;
           46: expected_byte=8'h00;
           47: expected_byte=8'h30;
           48: expected_byte=8'h00;
           49: expected_byte=8'h00;
           50: expected_byte=8'h46;
           51: expected_byte=8'h50;
           52: expected_byte=8'h47;
           53: expected_byte=8'h41;
           54: expected_byte=8'h01;
           55: expected_byte=8'h08;
           56: expected_byte=8'h01;
           57: expected_byte=8'h02;
           58: expected_byte=8'h00;
           59: expected_byte=8'h00;
           60: expected_byte=8'h00;
           61: expected_byte=8'h01;
           62: expected_byte=8'h00;
           63: expected_byte=8'h01;
           64: expected_byte=8'hB2;
           65: expected_byte=8'h07;
           66: expected_byte=8'h00;
           67: expected_byte=8'h00;
           68: expected_byte=8'h00;
           69: expected_byte=8'h01;
           70: expected_byte=8'h00;
           71: expected_byte=8'h01;
           72: expected_byte=8'h00;
           73: expected_byte=8'h02;
           74: expected_byte=8'h00;
           75: expected_byte=8'h00;
           76: expected_byte=8'h61;
           77: expected_byte=8'hA8;
           78: expected_byte=8'h00;
           79: expected_byte=8'h01;
           80: expected_byte=8'h00;
           81: expected_byte=8'h02;
           82: expected_byte=8'h00;
           83: expected_byte=8'h00;
           84: expected_byte=8'h00;
           85: expected_byte=8'h03;
           86: expected_byte=8'h54;
           87: expected_byte=8'h45;
           88: expected_byte=8'h43;
           89: expected_byte=8'h32;
           90: expected_byte=8'h97;
           91: expected_byte=8'h2E;
           92: expected_byte=8'hD5;
           93: expected_byte=8'h34;
          default: expected_byte=8'hXX;
        endcase
      end
    endfunction
    udp_ipv4_frame_tx dut(.clk(clk),.rst(rst),.packet_start(start),
      .payload(payload),.tx_byte(tx_byte),.tx_en(tx_en),.busy(busy),.packet_done(done));
    always @(negedge clk) begin
        if (!rst && tx_en) begin
            if (seen >= 94 || tx_byte !== expected_byte(seen))
                $fatal(1,"FULL Ethernet/IPv4/UDP/FCS byte[%0d] mismatch got=%02h expected=%02h",
                       seen,tx_byte,expected_byte(seen));
            if (seen<7 && tx_byte!==8'h55) $fatal(1,"Preamble mismatch byte %0d",seen);
            if (seen==7 && tx_byte!==8'hD5) $fatal(1,"SFD mismatch");
            if (seen==8 && tx_byte!==8'hFF) $fatal(1,"MAC broadcast mismatch");
            if (seen==20 && tx_byte!==8'h08) $fatal(1,"Ethertype high mismatch");
            if (seen==21 && tx_byte!==8'h00) $fatal(1,"Ethertype low mismatch");
            if (seen==50 && tx_byte!==8'h46) $fatal(1,"Payload magic mismatch");
            seen=seen+1;
        end
        if (done) done_seen=done_seen+1;
    end
    initial begin
        repeat(6) @(posedge clk);
        @(negedge clk);rst=0;
        @(negedge clk);start=1;
        @(negedge clk);start=0;
        repeat(140) @(negedge clk);
        if (seen!=94 || done_seen!=1)
            $fatal(1,"Expected 94 TX bytes and one done, got %0d / %0d",seen,done_seen);
        $display("UDP_FRAME_TEST_PASS: all 94 bytes verified (Ethernet IPv4 UDP payload FCS)");
        $finish;
    end
endmodule
